package handler
import("encoding/json";"net";"net/http";"go-repair-center/internal/service";"go-repair-center/internal/transport/http/dto";"go-repair-center/internal/transport/http/middleware";"go-repair-center/internal/transport/http/response")
type AuthHandler struct{auth *service.AuthService}
func NewAuthHandler(auth *service.AuthService)*AuthHandler{return &AuthHandler{auth:auth}}
func(h *AuthHandler)Register(w http.ResponseWriter,r *http.Request){var input dto.RegisterRequest;if err:=json.NewDecoder(r.Body).Decode(&input);err!=nil{writeError(w,r,err);return};user,err:=h.auth.Register(r.Context(),input.Username,input.Password,input.DisplayName);if err!=nil{writeError(w,r,err);return};delete(user,"password_hash");response.Created(w,user,middleware.RequestID(r.Context()))}
func(h *AuthHandler)Login(w http.ResponseWriter,r *http.Request){var input dto.LoginRequest;if err:=json.NewDecoder(r.Body).Decode(&input);err!=nil{writeError(w,r,err);return};host,_,_:=net.SplitHostPort(r.RemoteAddr);pair,err:=h.auth.Login(r.Context(),input.Username,input.Password,host);if err!=nil{writeError(w,r,err);return};response.Success(w,pair,middleware.RequestID(r.Context()))}
func(h *AuthHandler)Refresh(w http.ResponseWriter,r *http.Request){var input dto.RefreshRequest;if err:=json.NewDecoder(r.Body).Decode(&input);err!=nil{writeError(w,r,err);return};pair,err:=h.auth.Refresh(r.Context(),input.RefreshToken);if err!=nil{writeError(w,r,err);return};response.Success(w,pair,middleware.RequestID(r.Context()))}
func(h *AuthHandler)Logout(w http.ResponseWriter,r *http.Request){var input dto.RefreshRequest;if err:=json.NewDecoder(r.Body).Decode(&input);err!=nil{writeError(w,r,err);return};if err:=h.auth.Logout(r.Context(),input.RefreshToken);err!=nil{writeError(w,r,err);return};response.Success(w,map[string]bool{"logged_out":true},middleware.RequestID(r.Context()))}
func(h *AuthHandler)Me(w http.ResponseWriter,r *http.Request){user,err:=h.auth.Me(r.Context(),middleware.UserID(r.Context()));if err!=nil{writeError(w,r,err);return};response.Success(w,user,middleware.RequestID(r.Context()))}
func(h *AuthHandler)ChangePassword(w http.ResponseWriter,r *http.Request){var input dto.ChangePasswordRequest;if err:=json.NewDecoder(r.Body).Decode(&input);err!=nil{writeError(w,r,err);return};if err:=h.auth.ChangePassword(r.Context(),middleware.UserID(r.Context()),input.OldPassword,input.NewPassword);err!=nil{writeError(w,r,err);return};response.Success(w,map[string]bool{"changed":true},middleware.RequestID(r.Context()))}